// Mapping ServiceNow -> Feed servicedesk/tickets. Spiegelt connectors/mappings/servicenow_tickets.yaml.
// Der Import der Engine prüft Typ, Pflicht und geschlossene Listen je Zeile; hier wird nur umbenannt.
const DAMAGE = { 'Display': 'screen', 'Screen': 'screen', 'Battery': 'battery', 'Housing': 'housing', 'Water damage': 'water', 'Other': 'other' };
const RESOLUTION = { 'Repaired': 'repair', 'Replaced': 'replace', 'Open': 'open', 'In progress': 'open', '': 'open' };
const iso = (t) => (t && t.length >= 19 && t[10] === ' ') ? t.slice(0, 10) + 'T' + t.slice(11, 19) : (t || null);
const num = (t) => { if (t === null || t === undefined || t === '') return null; const n = Number(String(t).replace(',', '.')); return Number.isNaN(n) ? t : n; };
const val = (v) => (v && typeof v === 'object' && 'value' in v) ? v.value : v;
const records = $input.first().json.result || [];
let watermark = $getWorkflowStaticData('global').watermark || '';
const rows = records.map((r) => {
  const u = val(r.sys_updated_on) || '';
  if (u > watermark) watermark = u;
  return {
    ticket_id: val(r.number),
    serial: val(r.u_device_serial),
    contract_id: val(r.u_rental_contract) || null,
    opened_at: iso(val(r.opened_at)),
    closed_at: iso(val(r.closed_at)),
    damage_type: DAMAGE[val(r.u_damage_type)] ?? val(r.u_damage_type),
    resolution: RESOLUTION[val(r.u_resolution) || ''] ?? val(r.u_resolution),
    quote_eur: num(val(r.u_quote_eur)),
    repair_cost_eur: num(val(r.u_repair_cost_eur)),
    replacement_serial: val(r.u_replacement_serial) || null,
    repair_partner_ref: val(r.u_repair_partner) || 'Refurbishment and repair partner (role-only)',
  };
});
return [{ json: { rows, count: rows.length, watermark_candidate: watermark } }];

// Wasserzeichen erst nach erfolgreicher Antwort vorrücken (delivery_id vorhanden).
const resp = $input.first().json;
const wm = $('Auf Feed abbilden').first().json.watermark_candidate;
if (resp && resp.delivery_id && wm) { $getWorkflowStaticData('global').watermark = wm; }
return [{ json: { delivery_id: resp.delivery_id, rows_read: resp.rows_read, rows_new: resp.rows_new, n_unresolved: resp.n_unresolved, unresolved_by_reason: resp.unresolved_by_reason, already_ingested: resp.already_ingested, watermark: wm } }];
